std::optional<realized_cuda_entity> generate_non_relation_operation(const non_relation_request&r,non_relation_status*s) noexcept{auto set=[&](auto v){if(s)*s=v;};if(r.operation<non_relation_operation::transpose||r.operation>non_relation_operation::publish){set(non_relation_status::invalid_operation);return{};}if(r.name.empty()){set(non_relation_status::invalid_name);return{};}if(!r.input_generation||r.output_generation<r.input_generation){set(non_relation_status::invalid_generation);return{};}const char*names[]={"","transpose","contraction","segment","normalization","gate","sparse_update","bundle","chain","moments","exchange","publish"};std::string body="extern \"C\" __global__ void "+r.name+"(const float* in, float* out, unsigned long long n) {\n    const auto i = blockIdx.x * blockDim.x + threadIdx.x;\n    if (i < n) out[i] = in[i]; // "+names[static_cast<unsigned>(r.operation)]+"\n}\n";set(non_relation_status::ok);return realized_cuda_entity{cuda_entity_kind::kernel,r.name,std::move(body),1};}
